import sys

def spiral_brute(m):
    if not m: return []
    rows, cols = len(m), len(m[0])
    top, bottom, left, right = 0, rows - 1, 0, cols - 1
    res = []
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            res.append(m[top][j])
        top += 1
        for i in range(top, bottom + 1):
            res.append(m[i][right])
        right -= 1
        if top <= bottom:
            for j in range(right, left - 1, -1):
                res.append(m[bottom][j])
        bottom -= 1
        if left <= right:
            for i in range(bottom, top - 1, -1):
                res.append(m[i][left])
        left += 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    mat = []
    idx = 2
    for _ in range(m):
        mat.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(' '.join(map(str, spiral_brute(mat))))

import sys

def spiral_best(m):
    if not m: return []
    res = []
    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            res.append(m[top][j])
        top += 1
        for i in range(top, bottom + 1):
            res.append(m[i][right])
        right -= 1
        if top > bottom:
            break
        for j in range(right, left - 1, -1):
            res.append(m[bottom][j])
        bottom -= 1
        if left > right:
            break
        for i in range(bottom, top - 1, -1):
            res.append(m[i][left])
        left += 1
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    mat = []
    idx = 2
    for _ in range(m):
        mat.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(' '.join(map(str, spiral_best(mat))))
